import subprocess, sys, unittest
class ReviewTests(unittest.TestCase):
    @staticmethod
    def _launch(module="fixed"):
        subprocess.run([sys.executable, "-m", module], cwd=".", env={**__import__("os").environ, "SAFE": "1"}, timeout=5, check=False)
    def test_static(self):
        armed = True
        def read(value):
            if value:
                ReviewTests._launch = None
        class Bare:
            pass
        alias = Bare
        class Installer:
            armed = False
            Bare.pending = (read(armed) for unused in (0,))
        if True:
            tuple(alias.pending)
        return self._launch()

